const html = $input.item.json.data || '';
const url = ($input.item.json.url || '').replace(/\?.*/,'');

function extract(re, h, g=1){ const m=h.match(re); return m?(m[g]||'').replace(/<[^>]+>/g,'').trim():'' }
function countTag(tag,h){ return (h.match(new RegExp(`<${tag}[\\s>]`,'gi'))||[]).length }
function firstText(tag,h){ const m=h.match(new RegExp(`<${tag}[^>]*>([\\s\\S]{0,300}?)<\\/${tag}>`,'i')); return m?m[1].replace(/<[^>]+>/g,'').trim().substring(0,160):'' }

const title = extract(/<title[^>]*>([^<]{1,200})<\/title>/i, html);
const desc  = extract(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']{1,320})["']/i,html) ||
              extract(/<meta[^>]+content=["']([^"']{1,320})["'][^>]+name=["']description["']/i,html);

const h1Text = firstText('h1',html);
const h1Count = countTag('h1',html);
const h2Count = countTag('h2',html);
const h3Count = countTag('h3',html);
const h4Count = countTag('h4',html);
const h5Count = countTag('h5',html);

const canonical = extract(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']+)["']/i,html);
const robots    = extract(/<meta[^>]+name=["']robots["'][^>]+content=["']([^"']+)["']/i,html) ||
                  extract(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']robots["']/i,html) || 'index, follow';

const ogTitle = extract(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']{1,200})["']/i,html);
const ogDesc  = extract(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']{1,320})["']/i,html);
const ogImg   = extract(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']{1,300})["']/i,html);

const hasArticleSchema  = /<script[^>]+type=["']application\/ld\+json["'][^>]*>[\s\S]*?Article[\s\S]*?<\/script>/i.test(html);
const hasFAQSchema      = /<script[^>]+type=["']application\/ld\+json["'][^>]*>[\s\S]*?FAQPage[\s\S]*?<\/script>/i.test(html);
const hasBreadcrumb     = /<script[^>]+type=["']application\/ld\+json["'][^>]*>[\s\S]*?BreadcrumbList[\s\S]*?<\/script>/i.test(html);

const bodyText = html.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ');
const wordCount = bodyText.trim().split(/\s+/).filter(w=>w.length>2).length;

const imgTotal  = (html.match(/<img[\s>]/gi)||[]).length;
const imgNoAlt  = (html.match(/<img(?![^>]*alt=["'][^"']+["'])[^>]*>/gi)||[]).length;

function checkHierarchy(h){
  const tags=[]; const re=/<(h[1-6])[\s>]/gi; let m;
  while((m=re.exec(h))!==null) tags.push(parseInt(m[1].replace('h','')));
  if(!tags.length) return 'sem headings';
  for(let i=1;i<tags.length;i++) if(tags[i]>tags[i-1]+1) return 'quebrada';
  return 'ok';
}
const hierarchy = checkHierarchy(html);

let score=0;
const tl=title.length, dl=desc.length;
if(tl>=40&&tl<=60) score+=2; else if(tl>=30&&tl<=70) score+=1;
if(dl>=120&&dl<=160) score+=2; else if(dl>=80&&dl<=180) score+=1;
if(h1Count===1) score+=2; else if(h1Count>0) score+=1;
if(canonical) score+=1;
if(hierarchy==='ok') score+=1;
if(ogTitle) score+=1;
if(ogImg) score+=1;
if(hasArticleSchema) score+=1;
if(wordCount>=800) score+=1;

const issues=[];
if(!title)                         issues.push('Title ausente');
else if(tl<30||tl>70)              issues.push(`Title fora do range (${tl} chars — ideal 40-60)`);
if(!desc)                          issues.push('Meta description ausente');
else if(dl<80||dl>180)             issues.push(`Description fora do range (${dl} chars — ideal 120-160)`);
if(h1Count===0)                    issues.push('H1 ausente');
else if(h1Count>1)                 issues.push(`Múltiplos H1 (${h1Count})`);
if(!canonical)                     issues.push('Tag canonical ausente');
if(robots.includes('noindex'))     issues.push('Página com noindex — não será indexada');
if(hierarchy==='quebrada')         issues.push('Hierarquia de headings quebrada');
if(!ogTitle)                       issues.push('OG title ausente');
if(!ogImg)                         issues.push('OG image ausente');
if(!hasArticleSchema)              issues.push('Schema Article ausente');
if(wordCount<600)                  issues.push(`Conteúdo curto (${wordCount} palavras — mínimo 600)`);
if(imgNoAlt>0)                     issues.push(`${imgNoAlt} imagem(ns) sem alt text`);

return {
  url, title, title_length: tl,
  description: desc, description_length: dl,
  h1: h1Text, h1_count: h1Count, h2_count: h2Count, h3_count: h3Count, h4_count: h4Count, h5_count: h5Count,
  canonical: canonical||'ausente', robots,
  og_title: ogTitle||'ausente', og_description: ogDesc||'ausente', og_image: ogImg||'ausente',
  schema_article: hasArticleSchema?'sim':'não',
  schema_faq: hasFAQSchema?'sim':'não',
  schema_breadcrumb: hasBreadcrumb?'sim':'não',
  word_count: wordCount,
  img_total: imgTotal, img_sem_alt: imgNoAlt,
  heading_hierarchy: hierarchy,
  score_onpage: score,
  issues_onpage: issues.join(' | ') || 'nenhum',
  issues_count: issues.length
};

const item = $input.item.json;
const url = item.url || item.canonical || '';
return { json: { ...item, url: url, _url_encoded: encodeURIComponent(url) } };

const item = $input.item.json;

const score = item.score_onpage || 0;
const sessions = item.ga4_sessions || 0;
const position = item.gsc_avg_position || 0;
const ctr = item.gsc_ctr || 0;

let prioridade, prioridade_razao;
if (sessions >= 200 && score <= 6) {
  prioridade = 'P1'; prioridade_razao = 'Alto tráfego com SEO on-page fraco — impacto imediato';
} else if (sessions >= 200 && score >= 7 && (position > 10 || ctr < 2)) {
  prioridade = 'P1'; prioridade_razao = 'Alto tráfego mas posição ou CTR baixos — otimizar title/desc';
} else if ((sessions >= 50 && score <= 6) || (position > 10 && sessions >= 50)) {
  prioridade = 'P2'; prioridade_razao = 'Tráfego médio com oportunidade de melhoria';
} else if (sessions < 50 && score <= 4) {
  prioridade = 'P2'; prioridade_razao = 'Pouco tráfego e SEO fraco — potencial não explorado';
} else {
  prioridade = 'P3'; prioridade_razao = 'Página estável — monitorar';
}

const now = new Date();
const dataAuditoria = now.toLocaleDateString('pt-BR') + ' ' + now.toLocaleTimeString('pt-BR');

return { json: { ...item, prioridade, prioridade_razao, data_auditoria: dataAuditoria } };

const items = $input.all();

const urlsVistas = new Set();

return items
  .filter(item => {
    const content = item.json.body || item.json.data || '';
    if (/published:\s*false/i.test(content)) return false;
    return true;
  })
  .map(item => {
    const content = item.json.body || item.json.data || '';

    const permalinkMatch = content.match(/permalink:\s*["']?([^"'\n]+)["']?/);
    if (permalinkMatch) {
      const permalink = permalinkMatch[1].trim().replace(/^\/|\/$/g, '');
      return {
        json: {
          url: `https://meusite.com.br/${permalink}/`
        }
      };
    }

    const downloadUrl = item.json.download_url || '';
    let slug = downloadUrl.split('/').pop()?.replace(/\.md$/, '').split('?')[0] || '';
    slug = slug.replace(/^\d{4}-\d{2}-\d{2}-/, '');

    return {
      json: {
        url: `https://meusite.com.br/${slug}/`
      }
    };
  })
  .filter(item => {
    const url = item.json.url;
    if (!url || url === 'https://meusite.com.br//') return false;
    if (urlsVistas.has(url)) return false;
    urlsVistas.add(url);
    return true;
  });

const ga4Response = $input.item.json;
const onPage = $('Preparar URL para APIs').item.json;

const ga4Rows = ga4Response.rows || [];
let ga4 = { ga4_sessions:0, ga4_pageviews:0, ga4_bounce_rate:0, ga4_avg_session_sec:0, ga4_new_users:0 };
if (ga4Rows.length > 0) {
  const m = ga4Rows[0].metricValues;
  ga4 = {
    ga4_sessions: Math.round(parseFloat(m[0]?.value || 0)),
    ga4_pageviews: Math.round(parseFloat(m[1]?.value || 0)),
    ga4_bounce_rate: parseFloat((parseFloat(m[2]?.value || 0) * 100).toFixed(1)),
    ga4_avg_session_sec: Math.round(parseFloat(m[3]?.value || 0)),
    ga4_new_users: Math.round(parseFloat(m[4]?.value || 0))
  };
}

return { json: { ...onPage, ...ga4 } };

const gscResponse = $input.item.json;
const base = $('Enriquecer com GA4').item.json;

const gscRows = gscResponse.rows || [];
let totalClicks = 0, totalImpressions = 0, positions = [], queries = [];
gscRows.forEach(r => {
  totalClicks += r.clicks || 0;
  totalImpressions += r.impressions || 0;
  positions.push(r.position || 0);
  if (r.keys && r.keys[0]) queries.push(r.keys[0]);
});
const avgPosition = positions.length ? parseFloat((positions.reduce((a,b)=>a+b,0)/positions.length).toFixed(1)) : 0;
const avgCTR = totalImpressions ? parseFloat(((totalClicks/totalImpressions)*100).toFixed(2)) : 0;

const gsc = {
  gsc_clicks: totalClicks,
  gsc_impressions: totalImpressions,
  gsc_ctr: avgCTR,
  gsc_avg_position: avgPosition,
  gsc_top_queries: queries.slice(0,5).join(', ') || 'sem dados'
};

return { json: { ...base, ...gsc } };

const geminiItems = $input.all();
const gscItems = $('Enriquecer com GSC').all();

return geminiItems.map((item, idx) => {
  const geminiResp = item.json;
  const dadosCompletos = { ...(gscItems[idx]?.json || {}) };

  const camposRemover = ['candidates', 'usageMetadata', 'modelVersion', 'responseId', 'gemini_body'];
  camposRemover.forEach(campo => delete dadosCompletos[campo]);

  let geminiParsed = {};
  try {
    const rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const clean = rawText.replace(/```json|```/g, '').trim();

    // Tenta parse direto
    try {
      geminiParsed = JSON.parse(clean);
    } catch(e1) {
      // Tenta extrair só o bloco JSON principal
      const match = clean.match(/\{[\s\S]*\}/);
      if (match) {
        try {
          geminiParsed = JSON.parse(match[0]);
        } catch(e2) {
          geminiParsed = {};
        }
      }
    }
  } catch (e) {
    geminiParsed = {};
  }

  const temResposta = Object.keys(geminiParsed).length > 0;

  return {
    json: {
      ...dadosCompletos,
      prioridade: temResposta ? (geminiParsed.prioridade || dadosCompletos.prioridade || '') : dadosCompletos.prioridade || '',
      prioridade_razao: temResposta ? (geminiParsed.prioridade_razao || dadosCompletos.prioridade_razao || '') : dadosCompletos.prioridade_razao || '',
      data_auditoria: new Date().toLocaleDateString('pt-BR'),
      ia_resumo: geminiParsed.resumo_diagnostico || '',
      ia_potencial: geminiParsed.potencial_estimado || '',
      ia_recomendacoes: JSON.stringify(geminiParsed.recomendacoes || []),
      ia_sugestao_title: geminiParsed.sugestao_title || '',
      ia_sugestao_description: geminiParsed.sugestao_description || '',
      ia_oportunidades: geminiParsed.oportunidades_conteudo || '',
      elegibilidade_ai_overview: geminiParsed.elegibilidade_ai_overview || '',
      elegibilidade_ai_overview_razao: geminiParsed.elegibilidade_ai_overview_razao || '',
      score_llm: geminiParsed.score_llm || '',
      score_llm_razao: geminiParsed.score_llm_razao || '',
      geo_citabilidade_llm: geminiParsed.geo_citabilidade_llm || '',
      geo_gap_principal: geminiParsed.geo_gap_principal || '',
      geo_acao_prioritaria: geminiParsed.geo_acao_prioritaria || '',
      briefing_gem: geminiParsed.briefing_gem || '',
    }
  };
});

const item = $input.item.json;

const safe = (val, maxLen = 300) => String(val || '')
  .replace(/[\x00-\x1F\x22\x27\x5C]/g, ' ')
  .trim()
  .substring(0, maxLen);

const text = `Retorne APENAS o objeto JSON, sem texto antes ou depois, sem markdown, sem blocos de código. O JSON deve ser estritamente válido — todos os objetos devem estar corretamente fechados com chaves.

Você é um especialista em SEO para o site meusite.com.br. Analise os dados abaixo e retorne SOMENTE um JSON válido, sem texto adicional, sem markdown, sem explicações. O JSON deve ter exatamente estes campos: resumo_diagnostico (string), potencial_estimado (alta/media/baixa), recomendacoes (array de objetos com campo, acao, esforco, impacto), sugestao_title (string), sugestao_description (string), oportunidades_conteudo (string), prioridade (alta/media/baixa), prioridade_razao (string), elegibilidade_ai_overview (sim/nao/parcial), elegibilidade_ai_overview_razao (string), score_llm (número de 0 a 10), score_llm_razao (string), geo_citabilidade_llm (número de 0 a 10 indicando o quanto o conteúdo é citável por LLMs como ChatGPT e Gemini), geo_gap_principal (string descrevendo a principal lacuna de conteúdo para GEO — Generative Engine Optimization), geo_acao_prioritaria (string com a ação mais urgente para melhorar a presença em respostas geradas por IA), briefing_gem (string com um briefing resumido para o time de conteúdo sobre o que produzir ou melhorar nessa página considerando GEO).

URL: ${safe(item.url)}
Título: ${safe(item.title)}
Descrição: ${safe(item.description)}
H1: ${safe(item.h1)}
Score On-Page: ${safe(item.score_onpage)}
Sessões GA4: ${safe(item.ga4_sessions)}
Pageviews: ${safe(item.ga4_pageviews)}
Posição GSC: ${safe(item.gsc_avg_position)}
Cliques GSC: ${safe(item.gsc_clicks)}
Top queries: ${safe(item.gsc_top_queries, 200)}
Prioridade: ${safe(item.prioridade)}
Schema FAQ: ${safe(item.schema_faq)}
Schema Article: ${safe(item.schema_article)}
Word Count: ${safe(item.word_count)}
H2 Count: ${safe(item.h2_count)}
Issues Count: ${safe(item.issues_count)}`;

return {
  json: {
    ...item,
    gemini_body: JSON.stringify({
      contents: [{ parts: [{ text }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 8000 }
    })
  }
};
